function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50) return 'nums needs 1 to 50 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > nums.length)) return 'Each value is an integer from 1 to nums.length.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is an integer from 1 to nums.length.';
  const present = new Set(nums);
  for (let value = 1; value <= k; value++) if (!present.has(value)) return `nums must contain ${value} so that 1 to k can be collected.`;
  return null;
}

