function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? 50 : pick(1, 9);
  const k = rand() < 0.2 ? n : pick(1, n);
  const nums = [];
  for (let value = 1; value <= k; value++) nums.push(value);
  const top = rand() < 0.5 ? n : Math.max(1, Math.min(n, k + 2));
  while (nums.length < n) nums.push(pick(1, top));
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums, k];
}
